// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Product} from "../src/Product.sol";

contract InvMutTest is Test {
    Product c;
    function setUp() public { c = new Product(); }
    function testFuzz_property(address expectedController) public {
        vm.assume(expectedController != address(0) && expectedController != address(this));
        address actualController = address(c.controller());
        assertTrue(actualController != address(0x0000000000000000000000000000000000000001));
    }
}
